def.body:
begin
  if casting.unsafe?
    return
  end
  {% if T < Number || (T == Complex32) %}
        {% if (T == Complex) || (T == Complex32) %}
          raise TypeMismatchError.new("Cannot discard imaginary component") if !target.complex? && value.imag != 0
          real = value.real
        {% else %}
          real = value
        {% end %}
        if target.integer?
          raise TypeMismatchError.new("Cannot store fractional value as integer") unless real == real.trunc
          bits = target.precision.to_i
          low = target.signed? ? -(1_i128 << (bits - 1)) : 0_i128
          high = target.signed? ? (1_i128 << (bits - 1)) - 1 : (1_i128 << bits) - 1
          raise TypeMismatchError.new("Integer value out of range") unless real >= low && real <= high
        elsif target.float? || target.complex?
          bytes = target.complex? ? target.size // 2 : target.size
          converted = bytes == 4 ? real.to_f32.to_f64 : real.to_f64
          {% if T < Int %}
            exact = converted.finite? && converted.to_i128 == real
          {% else %}
            exact = converted == real || (converted.nan? && real.to_f64.nan?)
          {% end %}
          raise TypeMismatchError.new("Floating conversion would lose information") unless exact
          {% if (T == Complex) || (T == Complex32) %}
            if bytes == 4
              imag = value.imag.to_f32.to_f64
              raise TypeMismatchError.new("Imaginary conversion would lose information") unless imag == value.imag || (imag.nan? && value.imag.nan?)
            end
          {% end %}
        else
          Cleanup.with(TypeFactory.build(T)) { |source| check(source, target, casting) }
        end
      {% elsif T == String %}
        Codec.validate_strings([value], target, casting)
      {% else %}
        Cleanup.with(TypeFactory.build(T)) { |source| check(source, target, casting) }
      {% end %}
rescue OverflowError
  raise(TypeMismatchError.new("Value out of range"))
end

if count == 0
  Cleanup.with(TypeFactory.build(T)) do |target| CastingChecks.check(file_type, target, casting) end
  {% if T == String %}
          raise TypeMismatchError.new("Expected string datatype") unless file_type.string?
        {% elsif T == Bool %}
          raise TypeMismatchError.new("Expected Bool enum datatype") unless file_type.bool?
        {% elsif T == Reference %}
          raise TypeMismatchError.new("Expected object reference datatype") unless file_type.object_reference?
        {% end %}
  return [] of T
end
{% if T == String %}
        raise TypeMismatchError.new("Expected string datatype") unless file_type.string?
        read_strings(kind, id, file_type, memory, file, count)
      {% elsif T == Reference %}
        raise TypeMismatchError.new("Expected object reference datatype") unless file_type.object_reference?
        refs = Array(LibHDF5::Reference).new(count) { LibHDF5::Reference.new }
        begin
          transfer(true, kind, id, NativeType.for(Reference), memory, file, refs.to_unsafe.as(Void*))
        rescue exception
          refs.each_index { |i| Native.h5rdestroy(refs.to_unsafe + i) }
          raise exception
        end
        refs.map { |ref| Reference.new(ref, context) }
      {% elsif T < Array %}
        Cleanup.with(TypeFactory.build(T)) do |dtype|
          CastingChecks.check(file_type, dtype, casting)
          buffer = Array(LibHDF5::VLen).new(count) { LibHDF5::VLen.new }
          failed = false
          begin
            transfer(true, kind, id, dtype.id, memory, file, buffer.to_unsafe.as(Void*))
            Array(T).new(count) do |i|
              descriptor = buffer[i]
              Array({{ T.type_vars[0] }}).new(descriptor.len.to_i) { |j| descriptor.p.as({{ T.type_vars[0] }}*)[j] }
            end
          rescue exception
            failed = true
            raise exception
          ensure
            ret = Native.h5dvlen_reclaim(dtype.id, memory, LibHDF5::H5P_DEFAULT, buffer.to_unsafe.as(Void*))
            InternalChecks.ensure_herr(ret, "Failed to reclaim variable-length memory") unless failed
          end
        end
      {% elsif T == Bool %}
        raise TypeMismatchError.new("Expected Bool enum datatype") unless file_type.bool?
        Cleanup.with(TypeFactory.build(Bool)) do |dtype|
          buffer = Bytes.new(count)
          transfer(true, kind, id, dtype.id, memory, file, buffer.to_unsafe.as(Void*))
          buffer.map { |v| v != 0 }.to_a
        end
      {% elsif (T == Complex) || (T == Complex32) %}
        Cleanup.with(TypeFactory.build(T)) do |dtype|
          CastingChecks.check(file_type, dtype, casting)
          if file_type.integer? || file_type.float?
            values = read(kind, id, Float64, file_type, memory, file, count, context)
            values.map { |v| T.new(v, 0) }
          else
            raise TypeMismatchError.new("Unsupported complex datatype") unless file_type.complex?
            {% if T == Complex %}
              buffer = Array(LibHDF5::Complex64).new(count) { LibHDF5::Complex64.new }
            {% else %}
              buffer = Array(LibHDF5::Complex32).new(count) { LibHDF5::Complex32.new }
            {% end %}
            transfer(true, kind, id, dtype.id, memory, file, buffer.to_unsafe.as(Void*))
            buffer.map { |v| T.new(v.real, v.imag) }
          end
        end
      {% else %}
        Cleanup.with(TypeFactory.build(T)) do |dtype|
          CastingChecks.check(file_type, dtype, casting)
          buffer = Array(T).new(count) { T.zero }
          transfer(true, kind, id, dtype.id, memory, file, buffer.to_unsafe.as(Void*))
          buffer
        end
      {% end %}

Native.synchronize do
  @owned_children.reverse_each(&.close)
  @owned_children.clear
  if ctx = @context
    ctx.close(@id)
  elsif @id != LibHDF5::H5_INVALID_HID
    InternalChecks.ensure_herr(Native.h5tclose(@id), "Failed to close datatype")
  end
  @id = LibHDF5::H5_INVALID_HID
  @closed = true
end

if @id == LibHDF5::H5_INVALID_HID
  raise(ClosedObjectError.new("File is closed"))
end
@context.ensure_open(@id)
@id

Native.synchronize do
  {% if T == Int8 %}
          LibHDF5.h5t_native_int8_g
        {% elsif T == UInt8 %}
          LibHDF5.h5t_native_uint8_g
        {% elsif T == Int16 %}
          LibHDF5.h5t_native_int16_g
        {% elsif T == UInt16 %}
          LibHDF5.h5t_native_uint16_g
        {% elsif T == Int32 %}
          LibHDF5.h5t_native_int32_g
        {% elsif T == UInt32 %}
          LibHDF5.h5t_native_uint32_g
        {% elsif T == Int64 %}
          LibHDF5.h5t_native_int64_g
        {% elsif T == UInt64 %}
          LibHDF5.h5t_native_uint64_g
        {% elsif T == Float32 %}
          LibHDF5.h5t_native_float_g
        {% elsif T == Float64 %}
          LibHDF5.h5t_native_double_g
        {% elsif T == HDF5::Reference %}
          LibHDF5.h5t_std_ref_g
        {% else %}
          {% raise("Unsupported HDF5 type: #{T}") %}
        {% end %}
end

InternalChecks.ensure_herr(Native.h5open, "Failed to initialize HDF5")
{% if T == String %}
        Datatype.new(string_type.to_hdf5_type_id)
      {% elsif T == Bool %}
        base = storage ? LibHDF5.h5t_std_i8le_g : NativeType.for(Int8)
        id = InternalChecks.ensure_hid(Native.h5tenum_create(base), "Failed to create Bool datatype")
        begin
          f = 0_i8
          t = 1_i8
          InternalChecks.ensure_herr(Native.h5tenum_insert(id, "FALSE", pointerof(f).as(Void*)), "Failed to define FALSE")
          InternalChecks.ensure_herr(Native.h5tenum_insert(id, "TRUE", pointerof(t).as(Void*)), "Failed to define TRUE")
          Datatype.new(id)
        rescue exception
          Native.h5tclose(id)
          raise exception
        end
      {% elsif (T == Complex) || (T == Complex32) %}
        {% if T == Complex %}
          component = storage ? LibHDF5.h5t_ieee_f64le_g : NativeType.for(Float64)
          size = 16
        {% else %}
          component = storage ? LibHDF5.h5t_ieee_f32le_g : NativeType.for(Float32)
          size = 8
        {% end %}
        id = InternalChecks.ensure_hid(Native.h5tcreate(LibHDF5::TypeClass::Compound, size.to_u64), "Failed to create complex datatype")
        begin
          InternalChecks.ensure_herr(Native.h5tinsert(id, "r", 0_u64, component), "Failed to define real member")
          InternalChecks.ensure_herr(Native.h5tinsert(id, "i", (size // 2).to_u64, component), "Failed to define imaginary member")
          Datatype.new(id)
        rescue exception
          Native.h5tclose(id)
          raise exception
        end
      {% elsif T < Array %}
        Datatype.new(VLenType.for({{ T.type_vars[0] }}))
      {% else %}
        native = NativeType.for(T)
        if storage
          {% for name, global in {Int8: "i8", UInt8: "u8", Int16: "i16", UInt16: "u16", Int32: "i32", UInt32: "u32", Int64: "i64", UInt64: "u64"} %}
            {% if T.stringify == name.stringify %}
              native = LibHDF5.h5t_std_{{ global.id }}le_g
            {% end %}
          {% end %}
          {% if T == Float32 %}
            native = LibHDF5.h5t_ieee_f32le_g
          {% elsif T == Float64 %}
            native = LibHDF5.h5t_ieee_f64le_g
          {% end %}
        end
        Datatype.new(InternalChecks.ensure_hid(Native.h5tcopy(native), "Failed to copy datatype"))
      {% end %}

Native.synchronize do
  {% if T < Number %}
          type_id = Native.h5tvlen_create(NativeType.for(T))
          raise Error.new("Failed to create variable-length datatype") if type_id == LibHDF5::H5_INVALID_HID
          type_id
        {% else %}
          {% raise("Unsupported variable-length base type: #{T}") %}
        {% end %}
end
